// App members. One model worker, bounded chunks, no private local path in HTTP data.
void startLocalModelUpload(){if(!modelsAdmin()||modelBusy||modelActive)return;auto row=selectedModel();auto state=str(row,"state");if(state!="approved"&&state!="paused"&&state!="failed")throw std::runtime_error("승인된 모델 요청을 선택하세요. 검증 완료 파일은 기존 등록 기능을 사용하세요.");auto file=fileDialog(hwnd,false,L"모델 파일\0*.safetensors;*.gguf\0\0");if(file.empty())return;auto spec=row.at("spec");if(MessageBoxW(hwnd,(L"이 모델 파일을 서버로 보낼까요?\n\n"+modelReviewText(row)+L"\n\n파일의 SHA와 용량이 명세와 같아야 합니다. 검사가 끝나도 자동 활성화하지 않습니다.").c_str(),L"내 모델 파일 등록",MB_YESNO|MB_ICONQUESTION)!=IDYES)return;if(modelThread.joinable())modelThread.join();auto cfg=store->settings;auto owner=modelManagerOwner,scope=modelManagerScope;auto serial=++modelSerial;modelBusy=true;modelActive=true;modelLocalUploading=true;modelCancel=false;modelMessage=L"내 모델 파일 SHA 확인 중…";auto* target=engine;
try{modelThread=std::thread([this,cfg,owner,scope,serial,row,spec,file=fs::path(file),target]{CoInitializeEx(nullptr,COINIT_MULTITHREADED);auto key=str(row,"id");json result={{"owner",owner},{"scope",scope},{"serial",serial},{"action","local_upload"}};std::string token;auto progress=[&](const std::string& stage,uint64_t done,uint64_t total){target->event({"model_manager","","",{{"owner",owner},{"scope",scope},{"serial",serial},{"action","local_progress"},{"stage",stage},{"received",done},{"total",total}}});};try{NetworkScope network(&modelCancel,std::chrono::steady_clock::now()+std::chrono::hours(2),"standard");AccountOwnerScope binding(owner);auto total=spec.at("bytes").get<uint64_t>();if(total<1||total>32ULL*1024*1024*1024||fs::file_size(file)!=total)throw std::runtime_error("모델 파일 용량이 명세와 다릅니다.");auto modified=fs::last_write_time(file);auto hash=modelFileHash(file,modelCancel,total,[&](uint64_t done){progress("로컬 SHA 검사",done,total);});if(hash!=str(spec,"sha256")||fs::last_write_time(file)!=modified)throw std::runtime_error("모델 파일 SHA가 명세와 다르거나 검사 중 파일이 바뀌었습니다.");auto base=joinUrl(str(cfg,"api"),"/api/models/requests/"+key);auto send=[&](const std::string& suffix,const json& payload){auto response=request("POST",base+suffix,str(cfg,"api_key"),payload.dump(),"application/json",&modelCancel,1024*1024,30000);if(response.code==429)throw std::runtime_error("모델 전송 요청이 제한됐습니다. 잠시 후 이어받으세요.");return response.object();};auto start=send("/local-start",{{"expected_version",str(row,"version")}});token=str(start,"token");if(!boardId(token)||start.value("bytes",uint64_t(0))!=total||str(start,"sha256")!=hash)throw std::runtime_error("모델 전송 기준을 확인할 수 없습니다.");auto offset=start.value("offset",uint64_t(0));if(offset>total)throw std::runtime_error("모델 이어받기 위치 오류");std::ifstream input(fs::path(extendedWindowsPath(file)),std::ios::binary);if(!input)throw std::runtime_error("모델 파일을 다시 열지 못했습니다.");input.seekg(std::streamoff(offset));while(offset<total){if(modelCancel)throw std::runtime_error("모델 파일 보내기를 중지했습니다.");if(fs::file_size(file)!=total||fs::last_write_time(file)!=modified)throw std::runtime_error("모델 파일이 전송 중 바뀌었습니다.");auto count=size_t(std::min<uint64_t>(8*1024*1024,total-offset));std::string chunk(count,'\0');input.read(chunk.data(),std::streamsize(count));if(size_t(input.gcount())!=count)throw std::runtime_error("모델 파일을 끝까지 읽지 못했습니다.");auto response=request("POST",base+"/local-chunk?offset="+std::to_string(offset),str(cfg,"api_key"),chunk,"application/octet-stream",&modelCancel,65536,90000,{},token);if(response.code==429)throw std::runtime_error("모델 전송이 제한됐습니다. 잠시 후 이어받으세요.");auto next=response.object().value("offset",uint64_t(0));if(next!=offset+count)throw std::runtime_error("서버 전송 위치를 확인하지 못했습니다. 자동 재전송하지 않습니다.");offset=next;progress("서버로 전송",offset,total);}send("/local-finish",{{"token",token}});for(int i=0;i<3600;i++){if(modelCancel)throw std::runtime_error("모델 파일 검사를 중지했습니다.");auto response=request("GET",base,str(cfg,"api_key"),"","application/json",&modelCancel,1024*1024,15000);if(response.code==429)throw std::runtime_error("모델 상태 조회가 제한됐습니다. 잠시 후 새로고침하세요.");auto live=response.object();auto state=str(live,"state");if(state=="verified"){result["reply"]=live;token.clear();break;}if(state=="failed"||state=="paused"||state=="cancelled"||state=="rejected")throw std::runtime_error("서버에서 모델 검사를 완료하지 못했습니다. 요청 목록에서 사유를 확인하세요.");progress("서버 SHA·파일 형식 검사",live.value("verified_bytes",uint64_t(0)),total);for(int pause=0;pause<10&&!modelCancel;pause++)Sleep(100);}if(!result.contains("reply"))throw std::runtime_error("모델 검사 시간을 초과했습니다. 요청 목록에서 상태를 확인하세요.");
}catch(const std::exception& error){result["failed"]=true;result["message"]=modelCancel?"내 파일 전송을 중지했습니다. 다음에 이어받을 수 있습니다.":userError(error.what());if(!token.empty()){try{NetworkScope stop(nullptr,std::chrono::steady_clock::now()+std::chrono::seconds(3),"standard");AccountOwnerScope binding(owner);request("POST",joinUrl(str(cfg,"api"),"/api/models/requests/"+key+"/local-stop"),str(cfg,"api_key"),json{{"token",token}}.dump(),"application/json",nullptr,65536,3000);}catch(...){}}}CoUninitialize();modelActive=false;target->event({"model_manager","","",result});});}catch(...){modelBusy=false;modelActive=false;modelLocalUploading=false;throw std::runtime_error("로컬 모델 전송을 시작하지 못했습니다.");}}
